/**
 * App languages + translation dictionaries.
 *
 * English is the source language: components call t('some.key', 'English text'),
 * and if a translation is missing for the active language the English fallback is
 * shown. This makes partial coverage SAFE — untranslated strings never break the
 * UI — so translations can be expanded continuously post-launch.
 *
 * To translate a new string: add its key here under each language. To translate a new
 * screen: wrap its strings with t('key', 'English default') in the component.
 */
export const LANGUAGES = [
  { code: 'en', label: 'English',  native: 'English' },
  { code: 'hi', label: 'Hindi',    native: 'हिन्दी' },
  { code: 'te', label: 'Telugu',   native: 'తెలుగు' },
  { code: 'ta', label: 'Tamil',    native: 'தமிழ்' },
  { code: 'mr', label: 'Marathi',  native: 'मराठी' },
  { code: 'bn', label: 'Bengali',  native: 'বাংলা' },
];

/**
 * Normalize a service display name into its svc.* translation key.
 * e.g. "WiFi Setup" → "svc.wifi_setup", "Screen Replacement" → "svc.screen_replacement".
 * Use with t(): t(serviceNameKey(name), name) — falls back to the English name.
 */
// A ServicePro label's key from its English text, so a trade's own words ("Mechanics", "Garage & hours") translate too.
export function labelKey(label = '') {
  return 'sp.' + String(label).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

export function serviceNameKey(name = '') {
  return 'svc.' + name.toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

