    "sp.customers_see_these_on_your_profile_you_can_change_them_any_time": "வாடிக்கையாளர்கள் இவற்றை உங்கள் சுயவிவரத்தில் பார்ப்பார்கள். எப்போது வேண்டுமானாலும் மாற்றலாம்.",
