    "sp.under_name_we_check_it_before_customers_can_book_it_it_needs_a_price_a_skill_level_and_a_quality_check_behind_it_approved_jobs_start_in_your_city_only": "{name} கீழ். வாடிக்கையாளர்கள் முன்பதிவு செய்வதற்கு முன் நாங்கள் இதைச் சரிபார்க்கிறோம் - இதற்கு விலை, திறன் நிலை, தரச் சோதனை தேவை. அங்கீகரிக்கப்பட்ட வேலைகள் உங்கள் நகரத்தில் மட்டுமே தொடங்கும்.",
