    "sp.a_workshop_address_is_required_for_workshop_or_pickup_work": "பணிமனை அல்லது பிக்அப் வேலைக்குப் பணிமனை முகவரி தேவை",
    "sp.where_do_you_work": "நீங்கள் எங்கே வேலை செய்கிறீர்கள்?",
    "sp.pin_your_shop_then_say_how_far_around_it_you_will_go_jobs_outside_that_circle_never_reach_you": "உங்கள் கடையைப் பின் செய்து, அதைச் சுற்றி எவ்வளவு தூரம் செல்வீர்கள் என்று சொல்லுங்கள். அந்த வட்டத்துக்கு வெளியே உள்ள வேலைகள் உங்களுக்கு வராது.",
    "sp.your_shop_location": "உங்கள் கடை இருப்பிடம்",
    "sp.set_your_shop_location": "உங்கள் கடை இருப்பிடத்தை அமைக்கவும்",
    "sp.pin_dropped_on_the_map": "வரைபடத்தில் பின் இடப்பட்டது",
    "sp.drop_a_pin_where_your_shop_actually_is_everything_below_is_measured_from_it": "உங்கள் கடை உண்மையில் உள்ள இடத்தில் பின் இடுங்கள். கீழே உள்ள அனைத்தும் அதிலிருந்தே அளக்கப்படும்.",
    "sp.this_pin_is_km_km_from_your_shop_address_addr_customers_near_your_shop_will_not_see_you_tap_change_and_move_the_pin_to_your_shop": "இந்தப் பின் உங்கள் கடை முகவரியிலிருந்து {km} கி.மீ. தொலைவில் உள்ளது{addr}. உங்கள் கடைக்கு அருகிலுள்ள வாடிக்கையாளர்களுக்கு நீங்கள் தெரிய மாட்டீர்கள். மாற்று என்பதைத் தட்டி பின்னை உங்கள் கடைக்கு நகர்த்துங்கள்.",
    "sp.this_is_a_fixed_address_not_where_you_happen_to_be_jobs_are_matched_to_your_shop_even_when_you_are_out_you_can_hand_them_to_a_technician_from_anywhere": "இது நிலையான முகவரி, நீங்கள் இருக்கும் இடம் அல்ல. நீங்கள் வெளியே இருந்தாலும் வேலைகள் உங்கள் கடைக்கே இணைக்கப்படும் - எங்கிருந்தும் தொழில்நுட்பரிடம் ஒப்படைக்கலாம்.",
    "sp.city": "நகரம்",
    "sp.e_g_hyderabad": "எ.கா. ஹைதராபாத்",
    "sp.how_far_from_the_shop": "கடையிலிருந்து எவ்வளவு தூரம்",
    "sp.km": "கி.மீ.",
    "sp.measured_from_your_shop_pin_up_to_20_km_beyond_that_the_travel_costs_more_than_the_repair": "உங்கள் கடை பின்னிலிருந்து அளக்கப்படும். அதிகபட்சம் 20 கி.மீ. - அதற்கு மேல் பயணச் செலவு பழுதைவிட அதிகம்.",
