    "sp.zappyone_sets_the_fare_for_every_errand_like_a_ride_app_you_see_what_you_earn_on_each_errand_before_you_accept_it": "ZappyOne ஒவ்வொரு வேலைக்கும் ரைடு ஆப் போல கட்டணத்தை நிர்ணயிக்கிறது. ஏற்கும் முன் ஒவ்வொன்றிலும் நீங்கள் ஈட்டுவதைப் பார்க்கலாம்.",
    "sp.price_your_work_only_parts_are_different_every_time_so_you_add_them_on_the_quote_at_the_job_with_a_photo_the_customer_approves_and_zappyone_takes_nothing_on_parts": "உங்கள் வேலைக்கு மட்டும் விலை வையுங்கள். உதிரிபாகங்கள் ஒவ்வொரு முறையும் வேறுபடும், எனவே வேலை இடத்தில் புகைப்படத்துடன் மேற்கோளில் சேர்க்கவும்; வாடிக்கையாளர் ஒப்புதல் தருவார், உதிரிபாகங்களில் ZappyOne எதுவும் எடுக்காது.",
    "sp.sample_jobs_added_at_suggested_prices_change_any_price_or_remove_a_job": "மாதிரி வேலைகள் பரிந்துரைக்கப்பட்ட விலைகளில் சேர்க்கப்பட்டன. எந்த விலையையும் மாற்றலாம், அல்லது வேலையை நீக்கலாம்.",
