    "sp.your_pro_is_verified_your_payment_is_protected_and_our_team_stands_behind_every_job_if_anyone_asks_you_to_book_or_pay_outside_zappyone_say_no_and_tell_us": "உங்கள் ப்ரோ சரிபார்க்கப்பட்டவர், உங்கள் கட்டணம் பாதுகாக்கப்படுகிறது, ஒவ்வொரு வேலைக்கும் எங்கள் குழு துணை நிற்கிறது. ZappyOne-க்கு வெளியே முன்பதிவு செய்ய அல்லது பணம் செலுத்தச் சொன்னால் மறுத்துவிட்டு எங்களிடம் தெரிவியுங்கள்.",
    "sp.book_and_pay_only_on_zappyone_so_you_stay_protected_asked_to_go_outside_the_app_tell_us": "முன்பதிவும் கட்டணமும் ZappyOne-இல் மட்டுமே செய்யுங்கள், அப்போது நீங்கள் பாதுகாப்பாக இருப்பீர்கள். ஆப்புக்கு வெளியே செல்லச் சொன்னார்களா? எங்களிடம் சொல்லுங்கள்.",
    "sp.take_every_job_through_zappyone": "ஒவ்வொரு வேலையையும் ZappyOne மூலமே எடுங்கள்",
    "sp.zappyone_brings_you_customers_guarantees_your_payment_backs_you_in_any_dispute_and_grows_your_rating_a_job_taken_outside_the_app_has_none_of_that_and_taking_a_zappyone_customer_outside_ends_your_account": "ZappyOne உங்களுக்கு வாடிக்கையாளர்களைக் கொண்டு வருகிறது, உங்கள் கட்டணத்துக்கு உத்தரவாதம் தருகிறது, எந்தத் தகராறிலும் உங்களுக்கு ஆதரவாக நிற்கிறது, உங்கள் மதிப்பீட்டை உயர்த்துகிறது. ஆப்புக்கு வெளியே எடுத்த வேலைக்கு இவை எதுவும் இல்லை, ZappyOne வாடிக்கையாளரை வெளியே அழைத்துச் சென்றால் உங்கள் கணக்கு முடிக்கப்படும்.",
    "sp.keep_every_job_on_zappyone_guaranteed_payment_support_and_your_rating_taking_a_customer_outside_ends_your_account": "ஒவ்வொரு வேலையையும் ZappyOne-இலேயே வைத்திருங்கள்: கட்டண உத்தரவாதம், ஆதரவு, உங்கள் மதிப்பீடு. வாடிக்கையாளரை வெளியே அழைத்துச் சென்றால் உங்கள் கணக்கு முடிக்கப்படும்.",
