    "sp.your_zappyone_dues_are_over_the_limit_pay_now_and_the_job_is_yours_if_it_is_still_open": "உங்கள் ZappyOne நிலுவை வரம்பைத் தாண்டியுள்ளது. இப்போது செலுத்துங்கள், வேலை இன்னும் திறந்திருந்தால் அது உங்களுக்கே.",
