    "sp.report_that_the_customer_did_not_pay_they_are_told_their_next_booking_waits_until_it_is_paid_and_zappyone_follows_up": "வாடிக்கையாளர் பணம் செலுத்தவில்லை என்று புகாரளிக்கவா? அவர்களுக்குத் தெரிவிக்கப்படும், பணம் செலுத்தும் வரை அவர்களின் அடுத்த முன்பதிவு காத்திருக்கும், ZappyOne பின்தொடரும்.",
