    "sp.show_this_to_the_customer_they_scan_it_with_any_upi_app_the_amount_is_filled_in": "இதை வாடிக்கையாளருக்குக் காட்டுங்கள். அவர்கள் எந்த UPI ஆப்பிலும் ஸ்கேன் செய்வார்கள்; தொகை ஏற்கனவே நிரப்பப்பட்டிருக்கும்.",
    "sp.the_customer_pays_to_your_upi_id": "வாடிக்கையாளர் உங்கள் UPI ID-க்குச் செலுத்துவார்:",
