    "sp.the_customer_pays_you_by_upi_or_cash_tap_received_once_the_money_is_with_you": "வாடிக்கையாளர் UPI அல்லது ரொக்கமாகச் செலுத்துவார். பணம் கையில் கிடைத்ததும் \"பெற்றேன்\" என்பதைத் தட்டவும்.",
    "sp.it_includes_amt_they_owed_from_an_earlier_cancelled_booking": "இதில் முன்பு ரத்தான முன்பதிவிலிருந்து அவர்கள் செலுத்த வேண்டிய {amt} சேர்ந்துள்ளது.",
    "sp.the_customer_says_they_paid_amt_by_upi_at_time_find_it_in_your_upi_app_then_tap_received": "வாடிக்கையாளர் {time} மணிக்கு UPI மூலம் {amt} செலுத்தியதாகக் கூறுகிறார். உங்கள் UPI ஆப்பில் பார்த்து, பிறகு \"பெற்றேன்\" என்பதைத் தட்டவும்.",
    "sp.the_customer_says_they_paid_amt_by_upi_at_time_ref_utr_find_it_in_your_upi_app_then_tap_received": "வாடிக்கையாளர் {time} மணிக்கு UPI மூலம் {amt} செலுத்தியதாகக் கூறுகிறார், குறிப்பு {utr}. உங்கள் UPI ஆப்பில் பார்த்து, பிறகு \"பெற்றேன்\" என்பதைத் தட்டவும்.",
