    "sp.auto_accept_jobs": "வேலைகளைத் தானாக ஏற்கவும்",
    "sp.only_within": "இவ்வளவு தூரத்துக்குள் மட்டும்",
    "sp.paused_until_date_a_job_it_took_for_you_was_handed_back": "{date} வரை நிறுத்தப்பட்டது: உங்களுக்காக எடுத்த ஒரு வேலை திருப்பித் தரப்பட்டது.",
    "sp.off_turn_it_on_and_jobs_within_km_km_come_to_you_with_no_tap_while_you_are_online_and_free": "அணைக்கப்பட்டுள்ளது. இயக்கினால், நீங்கள் ஆன்லைனில் இருந்து, ஓய்வாக இருக்கும்போது {km} கி.மீ-க்குள் உள்ள வேலைகள் தட்டாமலே உங்களுக்கு வரும்.",
    "sp.on_jobs_within_km_km_are_yours_the_moment_they_come_in_while_you_are_online_and_free": "இயக்கத்தில் உள்ளது. நீங்கள் ஆன்லைனில் இருந்து, ஓய்வாக இருக்கும்போது {km} கி.மீ-க்குள் உள்ள வேலைகள் வந்தவுடனே உங்களுடையவை.",
    "sp.hand_back_a_job_it_took_and_auto_accept_pauses_for_n_days": "அது எடுத்த வேலையைத் திருப்பித் தந்தால் தானியங்கு ஏற்பு {n} நாட்களுக்கு நிறுத்தப்படும்.",
