    "sp.could_not_upload_the_photo_check_your_connection_and_try_again_if_it_keeps_failing_contact_support": "புகைப்படத்தைப் பதிவேற்ற முடியவில்லை. உங்கள் இணைப்பைச் சரிபார்த்து மீண்டும் முயலவும் - தொடர்ந்து தோல்வியுற்றால் ஆதரவைத் தொடர்புகொள்ளவும்.",
